//! 🔐️ Invalid consuming encoder receipts remain in their original receiving slot.
#[test]
fn native_local_original_invalid_encode_receipt_is_not_consumed(){let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../🛬️decode/🫴️recipient/🔁️continuation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut recipient=super::NativeEncodeRetirementRecipient::new();let receipt=super::NativeEncodeContinuation{work:crate::native_encoding::action::WorkState::fresh(),receiving:false,maximum_bytes:law["maximumNativeBytes"].as_u64().unwrap()as usize,ledger:Some(crate::native_receiving::NativeAllocationLedger::new(law["initialBytes"].as_u64().unwrap()as usize)),completed:law["invalidReceipt"]["completed"].as_u64().unwrap()as usize,total:law["invalidReceipt"]["total"].as_u64().unwrap()as usize,stage:0};let mut receipt=super::NativeRetirementEncodeContinuation{receipt:Some(receipt),recipient:&mut recipient};let before=receipt.owned_bytes();let mut accepted=|_|true;let error=receipt.encode(&mut accepted,|_|Ok(())).unwrap_err();assert_eq!(error.kind.as_str(),law["invalidReceipt"]["kind"].as_str().unwrap());assert_eq!(receipt.owned_bytes(),before);let(detached,_)=receipt.detach();assert_eq!(detached.owned_bytes(),before);}
